private readonly Channel<int> _channel = Channel.CreateBounded<int>(100);

public async Task ProduceAsync(CancellationToken ct)
{
    for (int i = 0; i < 1000; i++)
    {
        await _channel.Writer.WriteAsync(i, ct);
    }
    _channel.Writer.Complete();
}

public async Task ConsumeAsync(CancellationToken ct)
{
    await foreach (var item in _channel.Reader.ReadAllAsync(ct))
    {
        await ProcessItemAsync(item, ct);
    }
}

public async Task RunPipelineAsync(string[] filePaths, CancellationToken ct)
{
    var stage1 = Channel.CreateBounded<string>(50); // file paths
    var stage2 = Channel.CreateBounded<JsonNode>(50); // parsed JSON
    var stage3 = Channel.CreateBounded<Record>(50);   // database records

    var reader = Task.Run(() => ReadFilesAsync(filePaths, stage1.Writer, ct));
    var parser = Task.Run(() => ParseJsonAsync(stage1.Reader, stage2.Writer, ct));
    var writer = Task.Run(() => WriteToDatabaseAsync(stage2.Reader, stage3.Writer, ct));
    var sink = Task.Run(() => ArchiveAsync(stage3.Reader, ct));

    await Task.WhenAll(reader, parser, writer, sink);
}

private async Task ReadFilesAsync(string[] files, ChannelWriter<string> writer, CancellationToken ct)
{
    foreach (var file in files)
    {
        await writer.WriteAsync(file, ct);
    }
    writer.Complete();
}

private async Task ParseJsonAsync(ChannelReader<string> input, ChannelWriter<JsonNode> output, CancellationToken ct)
{
    await foreach (var file in input.ReadAllAsync(ct))
    {
        var json = await JsonNode.ParseAsync(File.OpenRead(file), ct);
        await output.WriteAsync(json, ct);
    }
    output.Complete();
}

private async Task WriteToDatabaseAsync(ChannelReader<JsonNode> input, ChannelWriter<Record> output, CancellationToken ct)
{
    await foreach (var node in input.ReadAllAsync(ct))
    {
        var record = MapToRecord(node);
        await output.WriteAsync(record, ct);
    }
    output.Complete();
}
